package com.hoteluq.pattern.structural;
import com.hoteluq.model.*;import com.hoteluq.service.ReservationService;import java.time.LocalDate;import java.util.List;
public class ReservationFacade {private final ReservationService service;public ReservationFacade(ReservationService service){this.service=service;}public Reservation book(User user,Room room,LocalDate in,LocalDate out,List<AdditionalService> extras,PaymentGateway payment){if(extras.stream().anyMatch(s->!s.available()))throw new IllegalStateException("Hay servicios no disponibles");double total=room.getPricePerNight()*java.time.temporal.ChronoUnit.DAYS.between(in,out)+extras.stream().mapToDouble(AdditionalService::price).sum();Reservation r=new Reservation(user,room,in,out,extras,total);service.confirmReservation(r,payment);return r;}}
